-- analytics views -------------------------------------------------------

CREATE VIEW v_accounts AS
SELECT
  account.id AS account_id,
  account.account_number,
  account.customer_id,
  customer.full_name AS customer_name,
  customer.segment,
  account_type.code AS account_type_code,
  account_type.name AS account_type_name,
  account_type.category AS account_category,
  account.branch_id,
  branch.name AS branch_name,
  region.name AS region_name,
  account.currency,
  account.opened_on,
  account.closed_on,
  account.status,
  account.current_balance_minor,
  account.is_test
FROM accounts account
JOIN customers customer ON customer.id = account.customer_id
JOIN account_types account_type ON account_type.id = account.account_type_id
JOIN branches branch ON branch.id = account.branch_id
JOIN regions region ON region.id = branch.region_id;

CREATE VIEW v_transactions AS
SELECT
  txn.id AS transaction_id,
  txn.transaction_ref,
  txn.booked_on,
  txn.type,
  txn.direction,
  txn.channel,
  txn.status,
  txn.currency,
  txn.amount_minor,
  txn.amount_usd_minor,
  txn.merchant_category,
  txn.card_id,
  txn.counterparty_account_id,
  txn.account_id,
  account.account_number,
  account.currency AS account_currency,
  account_type.code AS account_type_code,
  account_type.name AS account_type_name,
  account_type.category AS account_category,
  account.is_test,
  customer.id AS customer_id,
  customer.full_name AS customer_name,
  customer.segment,
  branch.name AS branch_name,
  region.name AS region_name
FROM transactions txn
JOIN accounts account ON account.id = txn.account_id
JOIN account_types account_type ON account_type.id = account.account_type_id
JOIN customers customer ON customer.id = account.customer_id
JOIN branches branch ON branch.id = account.branch_id
JOIN regions region ON region.id = branch.region_id;

COMMENT ON SCHEMA finance IS
  'Synthetic eval fixture: a fictional US retail bank with some EUR/GBP deposit accounts and a wealth-management arm. Money is stored in minor units. Transactions cover calendar 2024 and 2025 only.';
COMMENT ON COLUMN accounts.is_test IS
  'Synthetic sandbox account used for end-to-end testing. Its cards and transactions are excluded from reported figures by default.';
COMMENT ON COLUMN transactions.amount_usd_minor IS
  'amount_minor converted to US cents at the fx_rates rate of the booking month; equal to amount_minor on USD accounts.';
COMMENT ON COLUMN transactions.direction IS
  'CREDIT adds money to the account, DEBIT takes it out. amount_minor is always positive; direction carries the sign.';
COMMENT ON COLUMN account_types.category IS
  'DEPOSIT accounts hold customer money; CREDIT accounts (cards, lines of credit) carry a balance the customer owes.';
COMMENT ON VIEW v_transactions IS
  'One row per transaction. branch/region are the ACCOUNT branch, not the customer home branch.';
COMMENT ON TABLE fiscal_periods IS
  'One row per fiscal month. The fiscal year runs from 1 July to 30 June and is named by the calendar year it ends in.';
COMMENT ON COLUMN portfolios.is_test IS
  'Synthetic sandbox portfolio used for end-to-end testing. Its holdings and fees are excluded from reported figures by default.';
COMMENT ON COLUMN portfolios.branch_id IS
  'The branch that books and services the portfolio; it can differ from the customer home branch.';
COMMENT ON TABLE holdings IS
  'One row per position at each quarter-end (as_of): a point-in-time balance.';
COMMENT ON COLUMN holdings.cost_basis_cents IS
  'What the client paid for the position, in US cents. NULL for positions transferred in from another firm.';
COMMENT ON COLUMN fees.fiscal_period_id IS
  'The fiscal month the fee covers, which is not always the month it was charged.';
COMMENT ON COLUMN fees.charged_on IS
  'The day the fee was charged to the client. NULL while the fee is accrued and not yet billed.';

COMMIT;
